SOURCE='https://www.google.com/maps/place/Mujitech+%7C+Handy,+PC+%26+Laptop+Reparaturen/data=!4m2!3m1!1s0x0:0x397a5d917d61caeb'
def section(t,id):return '<section id="'+id+'">'+t+'</section>'
def apply(file,body,marker,before):
 p=ROOT/file;s=p.read_text()
 if 'id="'+marker+'"' not in s:
  assert before in s,file;s=s.replace(before,section(body,marker)+before,1)
 p.write_text(s)
for i,t in enumerate(TEXT):
 pref=PREFIX[i]
 # Existing, approved public review is reused with source attribution; no new case outcome invented.
 body='<h2>'+e(t['pc'])+'</h2><dl>'+''.join('<dt><strong>'+e(a)+'</strong></dt><dd>'+e(b)+'</dd>' for a,b in t['rows'])+'</dl>'
 body+='<p><a class="service-search-cta" href="'+pref+'anfrage.html#reparatur">'+e(t['ask'])+'</a></p><p><a href="'+pref+'privatkunden.html?service=PC-%2FLaptop-Optimierung#service-anfrage">'+e(t['help'])+'</a></p>'
 body+='<aside><h3>'+e(t['review'])+'</h3><blockquote><p>'+e(t['quote'])+'</p></blockquote><p><a href="'+SOURCE+'" target="_blank" rel="noopener noreferrer">'+e(t['source'])+'</a> · <a href="'+pref+'bewertungen.html">'+e(t['all'])+'</a></p></aside>'
 apply(PC[i],body,'computer-entscheidung','<section><h2>'+['Häufige Fragen','Common questions','Questions fréquentes','Domande frequenti'][i]+'</h2>')
 body='<h2>'+e(t['sam'])+'</h2><p>'+e(t['samp'])+'</p><h3>'+e(t['samcost'])+'</h3><p>'+e(t['samcostp'])+'</p><ul><li><a href="#guide-model">'+e(t['prices'])+'</a></li><li><a href="'+pref+CHARGE[i]+'">'+e(t['charge'])+'</a></li><li><a href="'+pref+'reparaturen.html#werkstatt-einblicke">'+e(t['photos'])+'</a></li></ul><p><a class="guide-price-link" href="'+pref+'anfrage.html#reparatur">'+e(t['samask'])+'</a></p>'
 f=SAM[i];apply(f,body,'samsung-entscheidung','<section id="repair-prices">')
 p=ROOT/f;s=p.read_text();s=re.sub(r'<title>.*?</title>','<title>'+e(t['title'])+'</title>',s,count=1);s=re.sub(r'(<meta name="description" content=")[^"]*',lambda m:m[1]+e(t['desc'],quote=True),s,count=1)
 for prop,value in [('og:title',t['title']),('og:description',t['desc'])]:s=re.sub(r'(<meta property="'+prop+r'" content=")[^"]*',lambda m:m[1]+e(value,quote=True),s,count=1)
 p.write_text(s)
